import { filingTitle, normaliseText } from '../helpers/text.js';

/** Returns the items whose title or author holds every word of the query, sorted by title as librarians file it (ignoring a leading 'The', 'A' or 'An'). */
export function searchCatalog(items, query) {
  const words = normaliseText(query).split(' ').filter(Boolean);
  if (words.length === 0) return [];
  return items
    .filter((item) => {
      const searchable = normaliseText(`${item.title} ${item.author}`);
      return words.every((word) => searchable.includes(word));
    })
    .sort(
      (first, second) =>
        filingTitle(first.title).localeCompare(filingTitle(second.title)) ||
        first.title.localeCompare(second.title),
    );
}

